import sys
import json
import math

def compute_entropy(counts):
    total = sum(counts.values())
    if total == 0:
        return 0.0
    H = 0.0
    for c in counts.values():
        if c <= 0:
            continue
        p = c / total
        H -= p * math.log2(p)
    return H

def main():
    raw = sys.stdin.read().strip()
    data = json.loads(raw)
    result = {}
    for node_id, signal_counts in data.items():
        H = compute_entropy(signal_counts)
        result[node_id] = {"entropy": round(H, 3)}
    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    main()
