import java.util.*;

public class Main {
    // 全局索引
    static int idx;
    static String json;

    public static void main(String[] args) {
        // 读取所有输入
        Scanner sc = new Scanner(System.in);
        json = sc.useDelimiter("\\A").next();
        sc.close();
        idx = 0;
        // 解析顶层对象，返回 Map<String, Map<String, Integer>>
        Map<String, Map<String, Integer>> data = parseTopLevel();
        // 计算结果
        Map<String, Map<String, Object>> result = new LinkedHashMap<>();
        for (String node : data.keySet()) {
            Map<String, Integer> counts = data.get(node);
            double entropy = computeEntropy(counts);
            Map<String, Object> entry = new LinkedHashMap<>();
            entry.put("entropy", roundToThree(entropy));
            result.put(node, entry);
        }
        // 输出 JSON
        System.out.println(mapToJson(result));
    }

    // 解析顶层对象，预期是 { "node": { "sig": int, ... }, ... }
    static Map<String, Map<String, Integer>> parseTopLevel() {
        skipWhitespace();
        expect('{');
        Map<String, Map<String, Integer>> map = new LinkedHashMap<>();
        if (peek() == '}') {
            idx++;
            return map;
        }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            expect(':');
            skipWhitespace();
            // 值应该是一个子对象
            Map<String, Integer> inner = parseInnerObject();
            map.put(key, inner);
            skipWhitespace();
            char c = json.charAt(idx);
            if (c == ',') {
                idx++;
                continue;
            } else if (c == '}') {
                idx++;
                break;
            } else {
                throw new RuntimeException("Unexpected char: " + c);
            }
        }
        return map;
    }

    // 解析内部对象：{ "sig": int, ... }
    static Map<String, Integer> parseInnerObject() {
        skipWhitespace();
        expect('{');
        Map<String, Integer> map = new LinkedHashMap<>();
        if (peek() == '}') {
            idx++;
            return map;
        }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            expect(':');
            skipWhitespace();
            int val = parseInteger();
            map.put(key, val);
            skipWhitespace();
            char c = json.charAt(idx);
            if (c == ',') {
                idx++;
                continue;
            } else if (c == '}') {
                idx++;
                break;
            } else {
                throw new RuntimeException("Unexpected char in inner: " + c);
            }
        }
        return map;
    }

    // 解析字符串，假定格式 "content"
    static String parseString() {
        skipWhitespace();
        expect('"');
        StringBuilder sb = new StringBuilder();
        while (idx < json.length()) {
            char c = json.charAt(idx);
            if (c == '"') {
                idx++;
                return sb.toString();
            }
            // 简单处理转义？
            sb.append(c);
            idx++;
        }
        throw new RuntimeException("Unterminated string");
    }

    // 解析整数（非负可能）
    static int parseInteger() {
        skipWhitespace();
        int sign = 1;
        if (json.charAt(idx) == '-') {
            sign = -1;
            idx++;
        }
        int num = 0;
        while (idx < json.length() && Character.isDigit(json.charAt(idx))) {
            num = num * 10 + (json.charAt(idx) - '0');
            idx++;
        }
        return sign * num;
    }

    static void skipWhitespace() {
        while (idx < json.length() && Character.isWhitespace(json.charAt(idx))) {
            idx++;
        }
    }

    static char peek() {
        skipWhitespace();
        return json.charAt(idx);
    }

    static void expect(char expected) {
        if (json.charAt(idx) != expected) {
            throw new RuntimeException("Expected " + expected + " but got " + json.charAt(idx));
        }
        idx++;
    }

    static double computeEntropy(Map<String, Integer> counts) {
        int total = 0;
        for (int v : counts.values()) total += v;
        if (total == 0) return 0.0;
        double H = 0.0;
        for (int c : counts.values()) {
            if (c <= 0) continue;
            double p = (double) c / total;
            H -= p * (Math.log(p) / Math.log(2)); // log2(p)
        }
        return H;
    }

    // 保留三位小数
    static String roundToThree(double val) {
        return String.format("%.3f", val);
    }

    // 将结果 Map 转换为 JSON 字符串
    static String mapToJson(Map<String, Map<String, Object>> map) {
        StringBuilder sb = new StringBuilder();
        sb.append("{");
        boolean first = true;
        for (String key : map.keySet()) {
            if (!first) sb.append(",");
            sb.append("\"").append(key).append("\":");
            // 内层 map，只有 "entropy": value
            Map<String, Object> inner = map.get(key);
            sb.append("{");
            sb.append("\"entropy\":").append(inner.get("entropy").toString()); // 值已经是格式化字符串
            sb.append("}");
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }
}
```

