#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <cmath>
#include <iomanip>
#include <sstream>
#include <cctype>
using namespace std;

class JSONParser {
public:
    JSONParser(const string& s) : json(s), idx(0) {}

    map<string, map<string, int>> parseTopLevel() {
        skipWhitespace();
        expect('{');
        map<string, map<string, int>> result;
        if (peek() == '}') { idx++; return result; }
        while (true) {
            skipWhitespace();
            string key = parseString();
            skipWhitespace();
            expect(':');
            skipWhitespace();
            map<string, int> inner = parseInnerObject();
            result[key] = inner;
            skipWhitespace();
            char c = json[idx];
            if (c == ',') {
                idx++;
                continue;
            } else if (c == '}') {
                idx++;
                break;
            } else {
                throw runtime_error("Unexpected char");
            }
        }
        return result;
    }

private:
    string json;
    size_t idx;

    void skipWhitespace() {
        while (idx < json.size() && isspace(json[idx])) idx++;
    }

    char peek() {
        skipWhitespace();
        return json[idx];
    }

    void expect(char ch) {
        if (json[idx] != ch) throw runtime_error("Expected char");
        idx++;
    }

    string parseString() {
        skipWhitespace();
        expect('"');
        string s;
        while (idx < json.size() && json[idx] != '"') {
            s.push_back(json[idx++]);
        }
        if (idx < json.size() && json[idx] == '"') idx++;
        return s;
    }

    int parseInteger() {
        skipWhitespace();
        int sign = 1;
        if (json[idx] == '-') { sign = -1; idx++; }
        int num = 0;
        while (idx < json.size() && isdigit(json[idx])) {
            num = num * 10 + (json[idx] - '0');
            idx++;
        }
        return sign * num;
    }

    map<string, int> parseInnerObject() {
        skipWhitespace();
        expect('{');
        map<string, int> map;
        if (peek() == '}') { idx++; return map; }
        while (true) {
            skipWhitespace();
            string key = parseString();
            skipWhitespace();
            expect(':');
            skipWhitespace();
            int val = parseInteger();
            map[key] = val;
            skipWhitespace();
            char c = json[idx];
            if (c == ',') {
                idx++;
                continue;
            } else if (c == '}') {
                idx++;
                break;
            } else {
                throw runtime_error("Unexpected char in inner");
            }
        }
        return map;
    }
};

double computeEntropy(const map<string, int>& counts) {
    int total = 0;
    for (auto& p : counts) total += p.second;
    if (total == 0) return 0.0;
    double H = 0.0;
    for (auto& p : counts) {
        int c = p.second;
        if (c <= 0) continue;
        double prob = (double)c / total;
        H -= prob * log2(prob);
    }
    return H;
}

// 将 double 保留三位小数转为字符串，避免科学计数法
string formatDouble(double val) {
    ostringstream oss;
    oss << fixed << setprecision(3) << val;
    return oss.str();
}

// 将结果转换为 JSON 输出
string mapToJson(const map<string, double>& res) {
    // 内部结构是每个节点映射到熵值，我们需要输出 {"node":{"entropy":val}, ...}
    // 但 res 是 node->entropy 的映射
    ostringstream oss;
    oss << "{";
    bool first = true;
    for (auto& p : res) {
        if (!first) oss << ",";
        oss << "\"" << p.first << "\":{\"entropy\":" << formatDouble(p.second) << "}";
        first = false;
    }
    oss << "}";
    return oss.str();
}

int main() {
    // 读取全部标准输入
    string input;
    string line;
    while (getline(cin, line)) {
        input += line;
    }
    JSONParser parser(input);
    auto data = parser.parseTopLevel();
    // 计算结果，保留插入顺序用 map，这里用 map 会自动排序，但题目不要求顺序，可以
    map<string, double> entropies;
    for (auto& nodePair : data) {
        double H = computeEntropy(nodePair.second);
        entropies[nodePair.first] = H;
    }
    // 输出
    cout << mapToJson(entropies) << endl;
    return 0;
}
